const before = wb.getRange('Sheet1!H1:I7').getValues();
const deleted: number[] = [];
for (let r = 7; r >= 1; r--) {
  const [h, i] = before[r-1];
  if (i !== null && i !== '' && (h === null || h === '')) { wb.getRange(`Sheet1!${r}:${r}`).delete(); deleted.push(r); }
}
log('deleted', deleted.join(','));
